<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
wp_set_current_user( 1 );
function dc_test_assert($condition,$message){if(!$condition){throw new RuntimeException($message);}}
function dc_fixture_parts($path){$source=file_get_contents($path);preg_match('/<style[^>]*>(.*?)<\/style>/is',$source,$style);preg_match('/<body[^>]*>(.*?)<\/body>/is',$source,$body);return array($body[1]??$source,$style[1]??'');}
$evidence=new Design_Core_Elementor_Runtime_Evidence();
$run_id=wp_generate_uuid4();$created=array();$cleanup=static function()use(&$created,$run_id){foreach(array_unique(array_map('intval',$created)) as $post_id){if($run_id===get_post_meta($post_id,'_design_core_test_artifact',true)){wp_delete_post($post_id,true);}}};register_shutdown_function($cleanup);
try{
$migrator=new Design_Core_Elementor_Registry_Migrator();$migration=$migrator->migrate();dc_test_assert(!is_wp_error($migration),'Registry migration failed.');dc_test_assert($migrator->rollback(),'Registry rollback failed.');$migration=$migrator->migrate();dc_test_assert(!is_wp_error($migration),'Registry re-migration failed.');$evidence->record('registry-migration-rollback','pass',array('component_schema'=>Design_Core_Elementor_Component_Registry::SCHEMA_VERSION),'production-smoke');
