$tokens=new Design_Core_Elementor_Design_Token_Service();$tokens->save(array('colors'=>array('primary'=>'#173f35','accent'=>'#f4a261'),'typography'=>array('heading'=>array('font_family'=>'Inter','font_weight'=>'700')),'spacing'=>array('md'=>24),'radius'=>array('md'=>16)));$global=(new Design_Core_Elementor_Global_Style_Bridge())->sync('v3');dc_test_assert(!is_wp_error($global),'V3 global sync failed.');
$fixtures=array('marketing.html','saas.html','responsive.html');$converter=new Design_Core_Elementor_HTML_Converter();$roundtrip=true;foreach($fixtures as $fixture){list($html,$css)=dc_fixture_parts(DESIGN_CORE_ELEMENTOR_PATH.'tests/fixtures/'.$fixture);$result=$converter->convert_to_elementor($html,$css,'Benchmark '.$fixture);dc_test_assert('success'===($result['status']??''),'Conversion failed for '.$fixture.': '.($result['error']??'unknown'));dc_test_assert(4===(int)($result['design_ir']['schema_version']??0),'Design IR v4 missing for '.$fixture);dc_test_assert(1===(int)($result['build_plan']['build_plan_schema_version']??0),'BuildPlan v1 missing for '.$fixture);dc_test_assert(!empty($result['page_id']),'Page missing for '.$fixture);$page_id=(int)$result['page_id'];$created[]=$page_id;update_post_meta($page_id,'_design_core_test_artifact',$run_id);$stored=json_decode((string)get_post_meta($page_id,'_elementor_data',true),true);$document=\Elementor\Plugin::instance()->documents->get($page_id);$reloaded=$document&&method_exists($document,'get_elements_data')?$document->get_elements_data():$stored;$rendered=\Elementor\Plugin::instance()->frontend->get_builder_content_for_display($page_id,true);if(empty($stored)||empty($reloaded)||''===trim((string)$rendered)){$roundtrip=false;}}
dc_test_assert($roundtrip,'Elementor save/reload/render round trip failed.');$evidence->record('elementor-save-reload-render','pass',array('pages'=>count($created)),'production-smoke');
$page_a='<section><article class="dc-smoke-card"><h4>A</h4><p>One</p></article></section>';$page_b='<section><article class="dc-smoke-card"><h4>B</h4><p>Two</p></article></section>';$a=$converter->convert_to_elementor($page_a,'.dc-smoke-card{padding:24px;border-radius:16px}','Reuse A');$b=$converter->convert_to_elementor($page_b,'.dc-smoke-card{padding:99px;border-radius:2px}','Reuse B');dc_test_assert(!empty($a['page_id'])&&!empty($b['page_id']),'Reuse benchmark pages failed.');foreach(array((int)$a['page_id'],(int)$b['page_id']) as $page_id){$created[]=$page_id;update_post_meta($page_id,'_design_core_test_artifact',$run_id);}dc_test_assert('native-compose'===($a['build_plan']['items'][0]['strategy']??'')&&'reuse-component'===($b['build_plan']['items'][0]['strategy']??''),'Page B did not execute through reuse-component.');$master_ids=array_column(array_merge($a['reuse']??array(),$b['reuse']??array()),'master_id');dc_test_assert(count(array_unique($master_ids))===1,'Page A and Page B did not share one component master.');$master=(new Design_Core_Elementor_Component_Registry())->get($master_ids[0]??'');dc_test_assert(in_array((int)$a['page_id'],$master['usage']['locations']??array(),true)&&in_array((int)$b['page_id'],$master['usage']['locations']??array(),true),'Component usage does not include both pages.');$page_instances=array_filter($master['instances']??array(),static function($instance)use($a,$b){return in_array((int)($instance['location']??0),array((int)$a['page_id'],(int)$b['page_id']),true);});dc_test_assert(2===count($page_instances),'Instance content was not stored independently.');$evidence->record('page-a-page-b-reuse','pass',array('page_a'=>(int)$a['page_id'],'page_b'=>(int)$b['page_id'],'master_id'=>$master_ids[0]??''),'production-smoke');
